const out = [];

for (const item of $input.all()) {
  const j = item.json;

  const get = (k) =>
    (j[k] === undefined || j[k] === null)
      ? ''
      : String(j[k]).trim();

  const parentName = get('Parent Name');
  const phone = get('Phone Number');
  const email = get('Email');
  const studentName = get('Student Name');
  const studentAge = get('Student Age');
  const currentGrade = get('Current Grade');
  const interestedGrade = get('Interested Grade');
  const enrollDate = get('Preferred Enrollment Date');
  const program = get('Interested Program');

  const message =
    get('Parent Message') ||
    get('Parent Message / Question') ||
    get('Parent Message/Question');

  const missing = [];

  if (!parentName) missing.push('Parent Name');
  if (!phone) missing.push('Phone Number');
  if (!studentAge) missing.push('Student Age');
  if (!interestedGrade) missing.push('Interested Grade');
  if (!message) missing.push('Parent Message');

  const isValid = missing.length === 0;

  const now = new Date();

  const pad = (n) => String(n).padStart(2, '0');

  const ymd =
    String(now.getFullYear()) +
    pad(now.getMonth() + 1) +
    pad(now.getDate());

  const rand =
    Math.random()
      .toString(16)
      .slice(2, 6)
      .toUpperCase();

  const leadId = 'SCH-' + ymd + '-' + rand;

  const normalize = (v) =>
    String(v || '')
      .trim()
      .toLowerCase()
      .replace(/\s+/g, '');

  const duplicateKey =
    normalize(phone) + '|' + normalize(studentName);

  const submissionSignature = [
    normalize(parentName),
    normalize(phone),
    normalize(email),
    normalize(studentName),
    normalize(studentAge),
    normalize(currentGrade),
    normalize(interestedGrade),
    normalize(enrollDate),
    normalize(program),
    normalize(message),
  ].join('|');

  out.push({
    json: {
      leadId,
      duplicateKey,
      submissionSignature,
      isValid,
      missingFields: missing.join(', '),
      errorMessage: isValid
        ? ''
        : 'Missing required information',
      processingStartedTime: now.toISOString(),
      parentName,
      phone,
      email,
      studentName,
      studentAge,
      currentGrade,
      interestedGrade,
      enrollDate,
      program,
      message,
    }
  });
}

return out;

