const item = $input.first().json;
const output = item.output || {};

const leadScore = Number(output.lead_score || 0);

let finalPriority = 'COLD';

if (leadScore >= 85) {
  finalPriority = 'HOT';
} else if (leadScore >= 60) {
  finalPriority = 'WARM';
}

return [{
  json: {
    ...item,
    output: {
      ...output,
      priority: finalPriority
    }
  }
}];

